import { createHash } from 'node:crypto';
import { z } from 'zod';

export function createPromptTemplate<TSchema extends z.ZodObject<z.ZodRawShape>>(config: {
  readonly id: string;
  readonly version: string;
  readonly inputSchema: TSchema;
  readonly systemPrompt: string;
  readonly renderUser: (safeInput: z.infer<TSchema>) => string;
}) {
  const schemaKey = JSON.stringify(Object.keys(config.inputSchema.shape).sort());
  const contentHash = createHash('sha256')
    .update(`${config.id}:${config.version}:${config.systemPrompt}:${schemaKey}`)
    .digest('hex')
    .slice(0, 12);

  return {
    id: config.id,
    version: config.version,
    contentHash,
    render(rawInput: z.input<TSchema>) {
      const validated = config.inputSchema.parse(rawInput);
      return { contentHash, system: config.systemPrompt, user: config.renderUser(validated) };
    }
  };
}

import { randomBytes } from 'node:crypto';

export function sanitizeAndWrapUntrusted(tag: string, rawValue: string): string {
  const clean = rawValue
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\u202A-\u202E\u2066-\u2069]/g, '')
    .trim();
  const nonce = randomBytes(4).toString('hex');
  const safeTag = `${tag.replace(/[^a-z0-9_]/gi, '_')}_${nonce}`;
  return `<${safeTag} untrusted="true">\n${clean.replace(new RegExp(`</${safeTag}>`, 'gi'), `&lt;/${safeTag}&gt;`)}\n</${safeTag}>`;
}

async function retryStage<T>(maxRetries: number, fn: () => Promise<T>, validate: (v: T) => boolean): Promise<T> {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const out = await fn();
    if (validate(out)) return out;
  }
  throw new Error('Stage failed deterministic validation gate');
}

export async function runPolicyChain(doc: string, deps: ChainDeps) {
  const clauses = await retryStage(2, () => deps.extractClauses(doc), (c) => c.length > 0);
  const risks = await retryStage(2, () => deps.evaluatePolicies(clauses), (r) => r.checksCompleted);
  return deps.formatReport(risks);
}

export interface ContractAnalysisDeps {
  runExtractor: (domain: 'financial' | 'sla' | 'privacy', text: string) => Promise<string[]>;
  runAuditor: (findings: { financial: string[]; sla: string[]; privacy: string[] }) => Promise<string>;
}

export async function analyzeContractParallelChain(contractText: string, deps: ContractAnalysisDeps) {
  const [financial, sla, privacy] = await Promise.all([
    deps.runExtractor('financial', contractText),
    deps.runExtractor('sla', contractText),
    deps.runExtractor('privacy', contractText)
  ]);
  if (financial.length + sla.length + privacy.length === 0) {
    return { status: 'APPROVED_NO_RISK' as const, report: null };
  }
  return { status: 'AUDITED' as const, report: await deps.runAuditor({ financial, sla, privacy }) };
}

import OpenAI from 'openai';
import { zodResponseFormat, zodTextFormat } from 'openai/helpers/zod';
import { z } from 'zod';

const openai = new OpenAI();
const TriageSchema = z.object({ severity: z.enum(['SEV1', 'SEV2']), affectedService: z.string() });

export async function triageResponsesApi(ticket: string) {
  const response = await openai.responses.parse({
    model: 'gpt-4o-mini', temperature: 0,
    input: [{ role: 'system', content: 'Classifique o incidente.' }, { role: 'user', content: ticket }],
    text: { format: zodTextFormat(TriageSchema, 'incident_triage') }
  });
  if (!response.output_parsed) throw new Error('Saída ausente (refusal ou truncamento).');
  return response.output_parsed;
}

export async function triageChatCompletions(ticket: string) {
  const completion = await openai.chat.completions.parse({
    model: 'gpt-4o-mini', temperature: 0,
    messages: [{ role: 'system', content: 'Classifique o incidente.' }, { role: 'user', content: ticket }],
    response_format: zodResponseFormat(TriageSchema, 'incident_triage')
  });
  const msg = completion.choices[0]?.message;
  if (msg?.refusal || !msg?.parsed) throw new Error('Refusal ou falha.');
  return msg.parsed;
}

